def prebuild():
    """Fill the 5/6/7-card rank table (~1 s) so act() never misses."""
    if _BUILT[0]:
        return
    _BUILT[0] = True
    counts = [0] * 13

    def rec(n, start, prod):
        if n == 0:
            if prod not in RT:
                RT[prod] = _rank_score(counts)
            return
        for r in range(start, 13):
            if counts[r] < 4:
                counts[r] += 1
                rec(n - 1, r, prod * _PR[r])
                counts[r] -= 1
    for k in (5, 6, 7):
        rec(k, 0, 1)


